import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int m = sc.nextInt();
    System.out.println(getResult(m));
  }

  public static String getResult(int m) {
    if (m <= 1 || m >= 100) return "ERROR!";

    CycleLinkedList list = new CycleLinkedList();
    for (int i = 1; i <= 100; i++) list.append(i);

    int idx = 1;
    Node cur = list.head;

    while (list.size >= m) {
      if (idx == m) {
        idx = 1;
        cur = list.remove(cur);
      } else {
        idx++;
        cur = cur.next;
      }
    }

    return list.toString();
  }
}

class Node {
  int val;
  Node prev;
  Node next;

  public Node(int val, Node prev, Node next) {
    this.val = val;
    this.prev = prev;
    this.next = next;
  }
}

class CycleLinkedList {
  Node head;
  Node tail;
  int size = 0;

  public void append(int val) {
    Node node = new Node(val, null, null);

    if (this.size > 0) {
      this.tail.next = node;
      node.prev = this.tail;
      this.tail = node;
    } else {
      this.head = node;
      this.tail = node;
    }
    this.head.prev = this.tail;
    this.tail.next = this.head;
    this.size++;
  }

  public Node remove(Node cur) {
    Node pre = cur.prev;
    Node nxt = cur.next;

    pre.next = nxt;
    nxt.prev = pre;

    cur.next = cur.prev = null;

    if (this.head == cur) {
      this.head = nxt;
    }

    if (this.tail == cur) {
      this.tail = pre;
    }
    this.size--;
    return nxt;
  }

  @Override
  public String toString() {
    StringJoiner sj = new StringJoiner(",");

    Node cur = this.head;
    for (int i = 0; i < this.size; i++) {
      sj.add(cur.val + "");
      cur = cur.next;
    }

    return sj.toString();
  }
}

import java.util.ArrayList;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int m = sc.nextInt();
    System.out.println(getResult(m));
  }

  public static String getResult(int m) {
    if (m <= 1 || m >= 100) return "ERROR!";

    ArrayList<Integer> arr = new ArrayList<>();
    for (int i = 1; i <= 100; i++) arr.add(i);

    return recursive(arr, m, 1);
  }

  public static String recursive(ArrayList<Integer> arr, int m, int count) {
    ArrayList<Integer> nxt = new ArrayList<>();

    for (Integer v : arr) {
      if (count == m + 1) {
        count = 1;
      }

      if (count++ % m != 0) {
        nxt.add(v);
      }
    }

    if (nxt.size() >= m) {
      return recursive(nxt, m, count);
    } else {
      StringJoiner sj = new StringJoiner(",");
      for (Integer v : nxt) sj.add(v + "");
      return sj.toString();
    }
  }
}

import java.util.ArrayDeque;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int m = sc.nextInt();
    System.out.println(getResult(m));
  }

  public static String getResult(int m) {
    if (m <= 1 || m >= 100) return "ERROR!";

    ArrayDeque<Integer> dq = new ArrayDeque<>();
    for (int i = 1; i <= 100; i++) dq.add(i);

    int idx = 1;
    while (dq.size() >= m) {
      if (idx == m) {
        dq.removeFirst();
        idx = 1;
      } else {
        dq.addLast(dq.removeFirst());
        idx++;
      }
    }

    StringJoiner sj = new StringJoiner(",");

    dq.stream().sorted((a, b) -> a - b).forEach(v -> sj.add(v + ""));

    return sj.toString();
  }
}

